// 1) 工厂模式：BeanFactory + FactoryBean
public interface BeanFactory {
    Object getBean(String name) throws BeansException;
    <T> T getBean(Class<T> requiredType) throws BeansException;
}
public interface FactoryBean<T> {
    T getObject() throws Exception;       // 返回产品对象
    Class<?> getObjectType();
    default boolean isSingleton() { return true; }
}
// getBean("mySqlSessionFactory") 返回产品 SqlSessionFactory
// getBean("&mySqlSessionFactory") 返回 FactoryBean 本身

// 2) 代理模式：AOP 选择 JDK 还是 CGLIB (DefaultAopProxyFactory)
class DefaultAopProxyFactory implements AopProxyFactory {
    public AopProxy createAopProxy(AdvisedSupport config) {
        if (config.isOptimize() || config.isProxyTargetClass() || !hasInterfaces(config)) {
            return new ObjenesisCglibAopProxy(config);   // 无接口或强制类代理
        }
        return new JdkDynamicAopProxy(config);            // 有接口走 JDK 动态代理
    }
}
// 自调用失效根因：this.foo() 调到原对象，拦截器链没机会执行
// 解法：注入自身 / getBean / 拆类 / AopContext.currentProxy()

// 3) 模板方法：JdbcTemplate.execute 把 SQL 作为回调传入
public <T> T execute(PreparedStatementCreator psc, PreparedStatementCallback<T> action) {
    Connection con = DataSourceUtils.getConnection(getDataSource());
    PreparedStatement ps = null;
    try {
        ps = psc.createPreparedStatement(con);
        applyStatementSettings(ps);
        return action.doInPreparedStatement(ps);          // 业务回调
    } catch (SQLException ex) {
        throw translateException("PreparedStatementCallback", getSql(psc), ex);
    } finally {
        JdbcUtils.closeStatement(ps);
        DataSourceUtils.releaseConnection(con, getDataSource()); // 模板兜底释放
    }
}

// 4) 观察者模式：事件发布 (默认同步)
@Component
class OrderListener {
    @EventListener(condition = "#event.amount > 1000")    // SpEL 过滤
    public void onPaid(OrderPaidEvent event) { /* ... */ }
}
@Service
class OrderService {
    @Autowired ApplicationEventPublisher publisher;
    @Transactional
    public void pay(Order o) {
        publisher.publishEvent(new OrderPaidEvent(o));    // 默认在当前线程串行通知
    }
}
